// =============================================================================
// src/exam/content.ts
// Authored exam content per level: a reading passage + comprehension questions,
// listening scripts + comprehension questions, and production prompts. A0
// reuses the A1 set. Strutture (grammar) items are generated by the quiz engine
// in builder.ts, not authored here.
// =============================================================================

import type { CefrLevel } from "../types/index.js";

export interface ComprehensionQ {
  question: string;
  options: string[];
  correctIndex: number;
}
export interface AscoltoContent {
  audioText: string;
  question: string;
  options: string[];
  correctIndex: number;
}
export interface LevelContent {
  passage: { title: string; text: string };
  lettura: ComprehensionQ[];
  ascolto: AscoltoContent[];
  scritta: { prompt: string; minWords: number };
  orale: { prompt: string; minWords: number };
}

