const CONTENT: Record<Exclude<CefrLevel, "A0">, LevelContent> = { A1, A2, B1, B2 };

/** Exam content for a level; A0 reuses the A1 set. */
export function contentForLevel(level: CefrLevel): LevelContent {
  return CONTENT[level === "A0" ? "A1" : level];
}
